entries[235662] = { ["name"] = "Emerald Snail", ["text"] = "Binds to Warband\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"This snail protects its treasures with the ferocity of a dragon, but perhaps not the speed.\"\nTrading Post" }
entries[235663] = { ["name"] = "Captured Twilight's Blade Banner", ["text"] = "Quest Item\nUse: Plant a Twilight's Blade banner on an ogre's corpse to sow enmity.\n\"Perfect for fooling an ogre into believing the Twilight's Blade has attacked.\"" }
entries[235664] = { ["name"] = "Ensemble: Topsy Turvy Mask Set", ["text"] = "Binds to Warband\nUse: Collect the green and purple appearances of the Topsy Turvy mask set.\n\"Join the carnival in your favorite flair of purple or green.\"" }
