entries[235700] = { ["name"] = "Reins of the Void-Scarred Gryphon", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nUse: Teaches you how to summon a Void-Scarred Gryphon.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Abandoned by its trainers the Void-Scarred Gryphon scrounged on any scrap of food that remained, most corrupted by the void. With the void now sustaining them, they only land when their fickle tastes are satisfied by untainted food that they just remember enjoying.\"\nDrop:\nVoid-Scarred Gryphon\nZone:\nVision of Stormwind (Revisited)" }
entries[235701] = { ["name"] = "Decaying Mecha-Scrapper Construction Kit", ["text"] = "Duration: 1 day (real time)\nUse: Creates a mechanical scrapbot that repairs equipment and buys nearly anything. The scrapbot leaves after 5 min. (15 Min Cooldown)\n\"Due to improper packaging, the components of this kit are steadily losing power.\"\nSell Price:" }
entries[235703] = { ["name"] = "Noggenfogger Select DOWN", ["text"] = "Use: Become slightly smaller. Stacks up to ten times.\n\"Shrinkage guaranteed! Now chuggable!\"\nSell Price:" }
entries[235704] = { ["name"] = "Noggenfogger Select UP", ["text"] = "Use: Become slightly larger. Stacks up to ten times.\n\"Tired of being looked down on? Now chuggable!\"\nSell Price:" }
entries[235705] = { ["name"] = "Void-Forged Stallion's Reins", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Forged just as their shoes once were, these beasts are less horses now and void energy in their likeness.\"\nDrop:\nVoid-Forged Stallion\nZone:\nVision of Stormwind (Revisited)" }
entries[235706] = { ["name"] = "Void-Scarred Pack Mother's Harness", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Fighting her corrupted handlers this pack mother freed herself and her pups. However, freedom from their handlers did not free them from the void in this lost place. She taught her pups to be even more dangerous beasts, and they now stalk throughout Orgrimmar fetching her food as all compete to survive.\"\nDrop:\nVoid-Scarred Pack Mother\nZone:\nVision of Orgrimmar (Revisited)" }
entries[235707] = { ["name"] = "Reins of the Void-Scarred Windrider", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nUse: Teaches you how to summon a Void-Scarred Windrider.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"When the void energies were released, it drove most windriders feral. They killed each other and their trainers. The gates to their roost were locked by the survivors. Some surviving windriders can still be seen gliding above, but none dare return to their new deadly domain to see what remains.\"\nDrop:\nVoid-Scarred Windrider\nZone:\nVision of Orgrimmar (Revisited)" }
entries[235709] = { ["name"] = "Ny'alothan Shadow Worm", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nSummons and dismisses your Ny'alothan Shadow Worm.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"A remnant of the Black Empire's past, these precursors of the abyss worms are once again resurging with the rise of Ny'alotha.\"\nAchievement:\nMastering the VisionsCategory:\nVisions of N'Zoth Revisited" }
entries[235710] = { ["name"] = "Noggenfogger Select FRESH", ["text"] = "Binds when picked up\nRaces: Goblin\nUse: Temporarily become cool.\n\"Wear the freshest clothes, eat at the chillest restaurants, and drink the hottest potions!\"\nSell Price:" }
entries[235711] = { ["name"] = "Corruption of the Aspects", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses the Corruption of the Aspects. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires the achievement We Have the Memories, fully unlocking all upgrades for the Hourglass of Horrific Visions.\n\n\"With N'Zoth's triumph, what started with Galakrond comes to fruition. With the Aspects gone, the corruption of their species is complete.\"\nVendor:\nTorie\nZone:\nDornogal\nCost:\n40000" }
entries[235712] = { ["name"] = "Void-Crystal Panther", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount will fly or run, depending on your riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"Although many precious gems have been corrupted by void energies in horrific visions, Master Jewelcrafters can still utilize them to craft mighty panther steeds.\"\nProfession:\nJewelcrafting" }
entries[235713] = { ["name"] = "Weird Sand", ["text"] = "Binds when picked up\nUse: Eat me.\n\"Dregs from the bottom of a Noggenfogger Select. Must be part of the recipe.\"" }
entries[235715] = { ["name"] = "Blue Floristar", ["text"] = "Quest Item\n\"Surrounded by velvety petals, the star-shaped center smells like lemon and the sea breeze.\"" }
entries[235716] = { ["name"] = "Ensemble: Cloak of Infinite Potential", ["text"] = "Binds to Warband\nUse: Collect the exclusive appearances of the Cloak of Infinite Potential.\n\"Includes exclusive Cloak of Infinite Potential appearances\"" }
