entries[236359] = { ["name"] = "Sargle's Fortune #1", ["text"] = "\"You're doomed!\"" }
entries[236365] = { ["name"] = "Sargle's Fortune #2", ["text"] = "\"Your problem just got worse. What have you done?\"" }
entries[236366] = { ["name"] = "Sargle's Fortune #3", ["text"] = "\"There's gold in your future, though it is not yours.\"" }
entries[236367] = { ["name"] = "Sargle's Fortune #4", ["text"] = "\"Are you happy? It won't last!\"" }
entries[236368] = { ["name"] = "Sargle's Fortune #5", ["text"] = "\"Your fondest wish will never come true.\"" }
entries[236369] = { ["name"] = "Sargle's Fortune #6", ["text"] = "\"There's no fortune for you. Go home.\"" }
entries[236370] = { ["name"] = "Sargle's Fortune #7", ["text"] = "\"Run!\"" }
entries[236371] = { ["name"] = "Sargle's Fortune #8", ["text"] = "\"The next sentence you hear is a lie.\"" }
entries[236372] = { ["name"] = "Sargle's Fortune #9", ["text"] = "\"Yes, it was all your fault.\"" }
entries[236373] = { ["name"] = "Sargle's Fortune #10", ["text"] = "\"Avoid all gnomes.\"" }
entries[236377] = { ["name"] = "Sargle's Fortune #11", ["text"] = "\"Ignore the previous fortune.\"" }
entries[236381] = { ["name"] = "Sargle's Fortune #12", ["text"] = "\"Caution! Poisoned food in your future.\"" }
entries[236387] = { ["name"] = "Sargle's Fortune #13", ["text"] = "\"Today is not your day.\"" }
