entries[236412] = { ["name"] = "\"Fireproof\" Punch", ["text"] = "Binds when picked up\nUse: See Flarendo up close with this potent fireproofing potion! Reduce Fire damage taken by 5% and increase Nature damage taken by 25%.\n\nOnly usable while fighting in the Cauldron of Carnage. (1 Min Cooldown)\n\"Common side effects include goosebumps, tremors, and mild nausea.\"\nSell Price:" }
