entries[236952] = { ["name"] = "Mote of Pure Void", ["text"] = "Crafting Reagent\n\"A solid orb of the nothingness that makes up the vast Twisting Nether. At least, you think it's solid. Can be bought and sold on the Auction House.\"\nSell Price:" }
